# Exact Record Retrieval demo: canonical-key index, tombstone check, byte-faithful read.
import hashlib
STORE={"rec-001":b"Title: Solar Sail Propulsion\nStatus: public draft\n","rec-002":b"Title: Tidal Array Maintenance\nStatus: public draft\n"}
CHECKS={k:hashlib.sha256(v).hexdigest() for k,v in STORE.items()}
TOMBSTONES={"rec-009"}
ALIASES={"old-id-1":"rec-001","TIDAL":"rec-002"}
def canonical(key):
    key=key.strip().lower()
    key=ALIASES.get(key,ALIASES.get(key.upper(),key))
    return key
def exact_read(key,version=None):
    k=canonical(key)
    if k in TOMBSTONES: return {"ok":False,"reason":"tombstoned"}
    if k not in STORE: return {"ok":False,"reason":"not found"}
    body=STORE[k]
    if hashlib.sha256(body).hexdigest()!=CHECKS[k]: return {"ok":False,"reason":"checksum mismatch"}
    return {"ok":True,"key":k,"bytes":len(body),"body":body.decode()}
for q in ["rec-001","OLD-ID-1"," rec-002 ","rec-009","rec-404"]:
    r=exact_read(q); print(q,"->",r["ok"],r.get("key",r.get("reason")))

